// Per-network settings, generated by `node scripts/sync-web.ts`. Mainnet has
// contractId null until the mainnet contract is deployed ("launching soon").
import networks from "./generated/networks.json";

export type Net = "testnet" | "mainnet";
export type NetConfig = (typeof networks)["testnet"] | (typeof networks)["mainnet"];

export const NETWORKS: Record<Net, NetConfig> = networks as Record<Net, NetConfig>;
export const NETS: Net[] = ["testnet", "mainnet"];
export const isNet = (s: string | undefined): s is Net => s === "testnet" || s === "mainnet";

/** True once the network has a deployed circle contract and treasurer. */
export const isLive = (c: NetConfig): c is NetConfig & { contractId: string; treasurerId: string } => Boolean(c.contractId && c.treasurerId);

export const txUrl = (c: NetConfig, hash: string) => `${c.explorer}/txns/${hash}`;
export const accountUrl = (c: NetConfig, id: string) => `${c.explorer}/address/${id}`;
export const repoFile = (path: string) => `${networks.testnet.repo}/blob/main/${path}`;
export const BOT = networks.testnet.botUsername;
